// TH16 v1.00a Stage 5 twin-boss non-spell 2 (Boss2p + Boss2Bp).
// Source: st05bs.ecl.txt Boss2p:716-775 / Boss2Bp:524-583.
// Dependencies: Boss2_at:585-629, Boss2_at1B:631-675, Boss2_at2:677-714,
//               Boss2B_at:397-439, Boss2B_at1B:441-483, Boss2B_at2:485-522.
// Entry state handed over by Boss:8-68 / BossB:1282-1337 (created in
// st05.ecl main:1605 and MainBoss:856): A at (64,128), B at (-64,128),
// source hurtbox 40x40 -> r20, hitbox 48x48 -> r24.
//
// Omitted per task policy / shell takeover: entry etCancel/etClear(640),
// killAllAsync/enmKillAll (previous-card cleanup), spellEnd/funcSet(0)/
// laserCancel/playSound/anm*, lifeMarker, stars, dropSeason, MISS/BOMB/
// CAPTURE counters.  The entry 120-frame invulnerability is superseded by
// the invulnerable training shell.

const TIME_LIMIT: int = 2644;    // 120 shell buffer + 2520 source window + 4
const OPENING_BUFFER: int = 120;

const TH16_TALISMAN: int = 528;  // source etSprite type 11
const TH16_BIG_BALL: int = 640;  // source etSprite type 18
const RING_COLOR_A: int = 4;     // etSprite(0,11,4)
const RING_COLOR_B: int = 10;    // etSprite(0,11,10)
const BALL_COLOR_A: int = 5;     // etSprite(1,18,5)
const BALL_COLOR_B: int = 2;     // etSprite(1,18,2)

// Boss2_at / Boss2_at1B ring EX (source etEx2 type 16 STEP, async 0,
// a=30/30/30/20, b=1, c=0, d=0, r=+30/-60/+90/-120 deg, s=-999999 keeps the
// launch speed).  Each segment draws speed*(1-t/a), then at the segment
// boundary restores the launch speed and applies the turn.  The deceleration
// is written with set_accel so the sequence stays inside the 16-slot limit.
// CW = Boss2_at (source), CCW = Boss2_at1B (source mirrored turns).
xformdef A_ZIGZAG_CW(speed: fx) {
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(30deg);
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(-60deg);
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(90deg);
    @20 set_accel(0fx - speed / 20fx);
    set_speed(speed);
    turn(-120deg);
    set_accel(0fx);
}

xformdef A_ZIGZAG_CCW(speed: fx) {
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(-30deg);
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(60deg);
    @30 set_accel(0fx - speed / 30fx);
    set_speed(speed);
    turn(-90deg);
    @20 set_accel(0fx - speed / 20fx);
    set_speed(speed);
    turn(120deg);
    set_accel(0fx);
}

// Boss2B_at / Boss2B_at1B ring EX: ANIM(1) then OFFSCREEN(240) then
// ANGLE_ACCEL(600, speed increment 0.016/frame, omega 0.011635528 rad/frame
// = 121 BAM).  Both turn off when the 600 frames expire.
xformdef B_SPIRAL {
    offscreen_keep(240);
    set_ang_vel(121 as angle);
    set_accel(0.016fx);
    @600 add_speed(0fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// ── Boss2_at / Boss2_at1B: mode 3 fixed ring, ANIM + STEP chain ────────────
// Source etCount 12/24/30/35 and etSpeed 3.0/3.0/3.5/3.5 (one layer; the
// 1.2f second endpoint is unused).  etDist(0,20) plus the ANIM entry
// position -= 4*speed gives net 20-4*speed along each bullet angle.
// invert=0 is Boss2_at (base decreases 2 deg per shot, CW turns),
// invert=1 is Boss2_at1B (base increases, CCW turns).
sub fire_ring_a(invert: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 35;
    var spd: fx = 3.5fx;
    if rank == RANK_EASY { n = 12; spd = 3.0fx; }
    if rank == RANK_NORMAL { n = 24; spd = 3.0fx; }
    if rank == RANK_HARD { n = 30; spd = 3.5fx; }
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, RING_COLOR_A);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, 20fx - 4fx * spd);
    if invert == 0 { sh_xform(0, A_ZIGZAG_CW(spd)); } else { sh_xform(0, A_ZIGZAG_CCW(spd)); }
    var base: angle = 90deg;
    for i in 0..10 {
        sh_angle(0, base, 0deg);
        sh_fire(0);
        wait(20);
        if invert == 0 { base = base - 2deg; } else { base = base + 2deg; }
    }
}

// ── Boss2B_at / Boss2B_at1B: same geometry, ANIM + OFFSCREEN + ANGLE_ACCEL ─
// Source etCount 12/24/30/35 and etSpeed 1.0/1.0/3.5/3.5 (one layer).
sub fire_ring_b(invert: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 35;
    var spd: fx = 3.5fx;
    if rank == RANK_EASY { n = 12; spd = 1.0fx; }
    if rank == RANK_NORMAL { n = 24; spd = 1.0fx; }
    if rank == RANK_HARD { n = 30; spd = 3.5fx; }
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, RING_COLOR_B);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, 20fx - 4fx * spd);
    sh_xform(0, B_SPIRAL);
    var base: angle = 90deg;
    for i in 0..10 {
        sh_angle(0, base, 0deg);
        sh_fire(0);
        wait(20);
        if invert == 0 { base = base - 2deg; } else { base = base + 2deg; }
    }
}

// ── Boss2_at2 / Boss2B_at2: mode 2 aimed ring, big ball, no EX beyond ANIM ─
// Source etCount 10/20/20/20, etSpeed 1.5/2.6/3.5/3.5, base angle 90 deg,
// two waves 25 frames apart, aim angle A recomputed at each etOn.
// etDist is called on emitter 0 while the configuration lives on emitter 1,
// so emitter 1 keeps distance 0; with the ANIM entry shift the bullet starts
// at -4*speed along its own angle from the boss centre.
sub fire_aimed_waves(shape: int, color: int, n: int, spd: fx) {
    var back: fx = 4fx * spd;
    for j in 0..2 {
        var base: angle = aim_player();
        for i in 0..n {
            var a: angle = base + 90deg + (i * 65536 / n) as angle;
            var x: fx = $self_x - back * cos(a);
            var y: fx = $self_y - back * sin(a);
            _ = fire(shape, color, x, y, spd, a, none, none);
        }
        wait(25);
    }
}

sub fire_aimed_a() {
    var rank: int = global(GVAR_RANK);
    var n: int = 20;
    var spd: fx = 3.5fx;
    if rank == RANK_EASY { n = 10; spd = 1.5fx; }
    if rank == RANK_NORMAL { n = 20; spd = 2.6fx; }
    fire_aimed_waves(TH16_BIG_BALL, BALL_COLOR_A, n, spd);
}

sub fire_aimed_b() {
    var rank: int = global(GVAR_RANK);
    var n: int = 20;
    var spd: fx = 3.5fx;
    if rank == RANK_EASY { n = 10; spd = 1.5fx; }
    if rank == RANK_NORMAL { n = 20; spd = 2.6fx; }
    fire_aimed_waves(TH16_BIG_BALL, BALL_COLOR_B, n, spd);
}

// ── moveRand(60,4,1.0f) with per-frame moveLimit ──────────────────────────
// Source moveLimit: A (-96,128,144,64) -> x[-168,-24] y[96,160];
// B (96,128,144,64) -> x[24,168] y[96,160].  Direction inner band is the
// limit centre +- width/4 (36) and y 112..144.  Speed drops 1-k/60 over 60
// steps, direction sampled once per call, per-frame clamp, no bounce.
sub arm_next_step(cx: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < cx - 72fx { nx = cx - 72fx; }
    if nx > cx + 72fx { nx = cx + 72fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_begin(cx: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < cx - 36fx {
        a = r / 3;
    } else if $self_x > cx + 36fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step(cx);
}

sub card_wait(frames: int, cx: fx) {
    for i in 0..frames {
        wait(1);
        arm_next_step(cx);
    }
}

// ── Boss2p entry (source 716-775) ─────────────────────────────────────────
// Wait(120) covers movePosTime(120,4,-64,128); moveLimitReset happens before
// it, moveLimit(-96,128,144,64) after it (kept by the moveRand helper).
async sub boss_a() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    move_to(120, -64fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    wait(60);
    loop {
        fire_ring_a(0);      // @Boss2_at
        wait(20);
        fire_aimed_a();      // @Boss2_at2
        move_rand_begin(-96fx);
        card_wait(70, -96fx);
        fire_ring_a(1);      // @Boss2_at1B
        wait(20);
        fire_aimed_a();      // @Boss2_at2
        move_rand_begin(-96fx);
        card_wait(70, -96fx);
    }
}

// ── Boss2Bp entry (source 524-583) ────────────────────────────────────────
async sub boss_b() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    move_to(120, 64fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    wait(60);
    loop {
        fire_ring_b(0);      // @Boss2B_at
        wait(20);
        fire_aimed_b();      // @Boss2B_at2
        move_rand_begin(96fx);
        card_wait(70, 96fx);
        fire_ring_b(1);      // @Boss2B_at1B
        wait(20);
        fire_aimed_b();      // @Boss2B_at2
        move_rand_begin(96fx);
        card_wait(70, 96fx);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(64fx, 128fx, 13000, 0, 0, 0, boss_a);
    _ = spawn_enemy(-64fx, 128fx, 15000, 0, 0, 0, boss_b);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Segment over: the two real bosses are not part of the phase-bound task
    // tree, so the control clears them silently at the end of the window.
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
